/** Preparar contexto para el Agente LangChain — regenerar con sync script */
const body = $json.body ?? $json;
const sessionId = String(body.sessionId || "").trim();
const text = String(body.text || "").trim();
const originalText = String(body.originalText || text).trim();

if (!sessionId || !text) {
  return [{ json: { ok: false, error: "sessionId y text requeridos" } }];
}

const staticData = $getWorkflowStaticData("global");
if (!staticData.sessions) staticData.sessions = {};

const prev = staticData.sessions[sessionId] || {
  turns: [],
  facts: {},
  pendingFields: {},
  lastSectionId: "",
  rutMode: "idle",
};

const incomingHistory = Array.isArray(body.history) ? body.history : [];
const history = (incomingHistory.length ? incomingHistory : prev.turns || []).slice(
  -16
);
const facts = { ...(prev.facts || {}), ...(body.facts || {}) };
const pendingFields = {
  ...(prev.pendingFields || {}),
  ...(body.pendingFields || {}),
};
const lastSectionId = String(body.lastSectionId || prev.lastSectionId || "");
const rutMode = String(body.rutMode || prev.rutMode || "idle");
const pageContext = body.pageContext || {};

const rawModel = String(body.model || "gemini-2.0-flash").trim();
const model = rawModel.startsWith("models/")
  ? rawModel
  : `models/${rawModel.replace(/^gemini-/, "gemini-")}`;

const ctxBits = [
  `pathname=${pageContext.pathname || "/"}`,
  `hash=${pageContext.hash || "(ninguno)"}`,
  `seccionVisible=${pageContext.sectionId || "(desconocida)"}`,
];
if (pageContext.sectionTitle) ctxBits.push(`titulo=${pageContext.sectionTitle}`);
if (pageContext.sectionBlurb) ctxBits.push(`resumen=${pageContext.sectionBlurb}`);
if (pageContext.rutStep) ctxBits.push(`rutPaso=${pageContext.rutStep}`);

const historyBlock = history.length
  ? history.map((t) => `${t.role}: ${t.text}`).join("\n")
  : "(sin historial previo)";

const agentUserMessage = [
  `SECCIÓN ACTUAL O ÚLTIMA: ${lastSectionId || "ninguna"}.`,
  `CONTEXTO DE PÁGINA: ${ctxBits.join(" | ")}.`,
  `HECHOS DE SESIÓN: ${JSON.stringify(facts)}.`,
  `RUT mode=${rutMode} | campos pendientes=${JSON.stringify(pendingFields)}.`,
  `TEXTO ORIGINAL STT: "${originalText}".`,
  `TEXTO CORREGIDO: "${text}".`,
  "",
  "HISTORIAL RECIENTE:",
  historyBlock,
  "",
  "Respondé al pedido del usuario. Si necesitás un id de sección, usá buscar_seccion.",
].join("\n");

return [
  {
    json: {
      ok: true,
      sessionId,
      text,
      originalText,
      history,
      facts,
      pendingFields,
      lastSectionId,
      rutMode,
      pageContext,
      model,
      agentUserMessage,
    },
  },
];

const input = typeof query === 'string' ? JSON.parse(query) : query;
const term = String(input.busqueda || input.query || '').toLowerCase().normalize('NFD').replace(/\p{M}/gu, '');
const sections = [{"id":"autoridades","title":"Autoridades","group":"institucional","summary":""},{"id":"mision","title":"Misión","group":"institucional","summary":""},{"id":"vision","title":"Visión","group":"institucional","summary":""},{"id":"funcion","title":"Función","group":"institucional","summary":""},{"id":"normativa","title":"Normativa Legal","group":"institucional","summary":""},{"id":"tramites","title":"Trámites","group":"tramites","summary":""},{"id":"rut","title":"RUT","group":"tramites","summary":"Registro Único de Tierras. Inscripción y declaración jurada a través del Sistema de Información Agrícola (SIA)."},{"id":"publicaciones-ia","title":"Consultas de publicaciones oficiales con IA","group":"publicaciones","summary":""},{"id":"economia-regional","title":"Economía regional","group":"publicaciones","summary":"Informes y análisis de economía regional agropecuaria."},{"id":"manejo-hidrico","title":"Manejo Hídrico","group":"publicaciones","summary":"Información sobre manejo del agua en sistemas productivos."},{"id":"fruticultura","title":"Fruticultura","group":"publicaciones","summary":"Publicaciones e informes del sector frutícola."},{"id":"horticultura","title":"Horticultura","group":"publicaciones","summary":"Publicaciones e informes del sector hortícola."},{"id":"frutos-secos","title":"Frutos Secos","group":"publicaciones","summary":"Información sobre frutos secos en Mendoza."},{"id":"cultivos-fruticolas","title":"Cultivos Frutícolas","group":"cultivos","summary":""},{"id":"durazno","title":"Durazno Industria","group":"cultivos","summary":"Informes, tableros e índices tecnológicos del durazno para industria."},{"id":"ciruela","title":"Ciruela","group":"cultivos","summary":"Informes tecnológicos, pronóstico de cosecha y reportes de ciruela."},{"id":"cereza","title":"Cereza","group":"cultivos","summary":"Información productiva y reportes de cereza."},{"id":"vid","title":"Vid","group":"cultivos","summary":"Información vinculada a vid y viticultura."},{"id":"fenologia","title":"Fenología","group":"cultivos","summary":"Estadios del cultivo a lo largo del año."},{"id":"cultivos-horticolas","title":"Cultivos Hortícolas","group":"cultivos","summary":""},{"id":"ajo","title":"Ajo","group":"cultivos","summary":"Informes y datos productivos de ajo."},{"id":"tomate","title":"Tomate Industria","group":"cultivos","summary":"Informes y datos productivos de tomate para industria."},{"id":"cinturon-verde","title":"Cinturón Verde","group":"cultivos","summary":"Información del cinturón verde mendocino."},{"id":"monitoreo-heladas","title":"Monitoreo de heladas","group":"monitoreo","summary":"Herramientas y tableros de monitoreo de heladas."},{"id":"monitoreo-catas","title":"Monitoreo de Catas","group":"monitoreo","summary":"Control sugerido y legislación relacionada a catas."},{"id":"herramientas","title":"Herramientas digitales agrícolas","group":"herramientas","summary":""},{"id":"agrometeorologia","title":"Agrometeorología","group":"herramientas","summary":"Datos y herramientas agrometeorológicas."},{"id":"mapas-agricolas","title":"Mapas Agrícolas","group":"herramientas","summary":"Mapas agrícolas de la provincia de Mendoza."},{"id":"estaciones","title":"Red de Estaciones Meteorológicas","group":"herramientas","summary":"Red de estaciones meteorológicas agrícolas."},{"id":"visor-agricola","title":"Visor Agrícola","group":"herramientas","summary":"Visor geoespacial agrícola."},{"id":"radar","title":"Radar meteorológico","group":"herramientas","summary":"Acceso a radar meteorológico."},{"id":"eventos-meteo","title":"Análisis de eventos meteorológicos","group":"herramientas","summary":"Análisis de eventos meteorológicos relevantes para la producción."},{"id":"bpa-herramienta","title":"Buenas Prácticas Agrícolas","group":"herramientas","summary":"Herramientas y recursos de Buenas Prácticas Agrícolas."},{"id":"precios","title":"Relevamiento de precios","group":"precios","summary":"Información clara y actualizada sobre precios al consumidor final de hortalizas, frutas y huevos en Mendoza. Informes semanales."},{"id":"ingenieria","title":"Ingeniería · ODK Central","group":"ingenieria","summary":"Vista técnica del relevamiento: QR de app user, formularios publicados y tablero simulado."},{"id":"odk-whatsapp","title":"WhatsApp de campo","group":"ingenieria","summary":"El ingeniero habla por WhatsApp y se arma una ficha simulada. No usa los XForms reales ni escribe en Central."},{"id":"odk-forms","title":"Formularios ODK","group":"ingenieria","summary":"XForms del proyecto Agricultura Mendoza: fenología, olivo y certificación de equipos."},{"id":"odk-flujo","title":"Flujo ODK Collect","group":"ingenieria","summary":"Pasos técnicos: escanear QR, bajar blancos, finalizar y enviar a Central."},{"id":"odk-tablero","title":"Tablero ODK","group":"ingenieria","summary":"Tablero simulado estilo Power BI para la campaña de formularios."},{"id":"odk-collect","title":"ODK Collect · ingeniería","group":"ingenieria","summary":"Vista técnica: QR de app user, formularios Central y tablero simulado. No es el trámite RUT."},{"id":"capacitaciones","title":"Capacitaciones","group":"capacitaciones","summary":""},{"id":"capacitacion-bpa","title":"Buenas Prácticas Agrícolas (capacitación)","group":"capacitaciones","summary":"Capacitación en BPA para producción sostenible, eficiente y responsable."},{"id":"encargado-finca","title":"Encargado de Finca","group":"capacitaciones","summary":"Programa de capacitación para encargados de cultivos frutícolas, hortícolas y vitícolas."}];
if (!term) return JSON.stringify({ ok: false, error: 'Indicá busqueda' });
const hits = sections.filter((s) => {
  const blob = [s.id, s.title, s.group, s.summary].join(' ').toLowerCase().normalize('NFD').replace(/\p{M}/gu, '');
  return blob.includes(term) || term.split(/\s+/).some((w) => w.length > 2 && blob.includes(w));
}).slice(0, 6);
return JSON.stringify({ ok: true, hits });

/** Formatear salida del Agente LangChain al contrato del webhook */
const ctx = $("Preparar contexto").first().json;
if (ctx.ok === false) {
  return [{ json: ctx }];
}

const staticData = $getWorkflowStaticData("global");
if (!staticData.sessions) staticData.sessions = {};

const rawOut = $json.output ?? $json.text ?? $json;
let intent =
  rawOut && typeof rawOut === "object" && !Array.isArray(rawOut)
    ? rawOut
    : null;

if (!intent && typeof rawOut === "string") {
  const m = rawOut.match(/\{[\s\S]*\}/);
  if (m) {
    try {
      intent = JSON.parse(m[0]);
    } catch {
      intent = null;
    }
  }
}

function knowledgeFallback(rawText) {
  const n = String(rawText || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/\p{M}/gu, "");
  let action = "describe";
  let target = undefined;
  let reply =
    "En esta demo del portal de Agricultura podés explorar cultivos, mapas, clima, precios, trámites y el RUT. Contame qué necesitás.";

  if (/ciruela|ciruelo/.test(n)) {
    target = "ciruela";
    reply =
      "Ciruela reúne informes y pronósticos del cultivo en Mendoza. ¿Querés que te lleve ahí?";
  } else if (/\bajo\b|a bajo/.test(n) && !/scroll|baja/.test(n)) {
    target = "ajo";
    reply = "Ajo tiene informes productivos en el portal. Te puedo marcar la sección.";
  } else if (/mapa/.test(n)) {
    target = "mapas-agricolas";
    reply = "Los mapas agrícolas muestran la producción por departamento.";
  } else if (/\brut\b|ruth|root/.test(n)) {
    action = "navigate";
    target = "rut";
    reply =
      "El RUT es el Registro Único de Tierras. Te marco la sección y te explico el trámite.";
  } else if (/que puedo|que se puede|para que sirve|como funciona/.test(n)) {
    reply =
      "Podés pedirme que te lleve a cualquier bloque del portal, que te explique un cultivo o trámite, que abra el sitio oficial, o arrancar la demo guiada. ¿Por dónde empezamos?";
  }

  return {
    action,
    target,
    openLink: false,
    openExternal: false,
    url: "",
    reply,
    extractedFields: {},
    fillMode: null,
    endSession: false,
    heardAs: "",
    remember: {},
  };
}

let via = "n8n-langchain";

if (!intent || !String(intent.reply || "").trim()) {
  intent = knowledgeFallback(ctx.text);
  via = "fallback-local";
}

const reply = String(intent.reply || "").trim();
const action = String(intent.action || "describe");
const target = intent.target ? String(intent.target) : undefined;

const facts = { ...ctx.facts };
for (const [k, v] of Object.entries(intent.remember || {})) {
  const clean = String(v || "").trim();
  if (clean) facts[k] = clean;
}

const pendingFields = { ...ctx.pendingFields };
if (intent.extractedFields && typeof intent.extractedFields === "object") {
  Object.assign(pendingFields, intent.extractedFields);
}

const turns = [
  ...ctx.history,
  { role: "user", text: ctx.text },
  { role: "assistant", text: reply },
].slice(-24);

staticData.sessions[ctx.sessionId] = {
  turns,
  facts,
  pendingFields,
  lastSectionId:
    target && ["navigate", "describe", "highlight"].includes(action)
      ? target
      : ctx.lastSectionId,
  rutMode: action === "open_rut" ? "collecting" : ctx.rutMode,
  updatedAt: Date.now(),
};

const keys = Object.keys(staticData.sessions);
if (keys.length > 200) {
  keys.sort(
    (a, b) =>
      (staticData.sessions[a].updatedAt || 0) -
      (staticData.sessions[b].updatedAt || 0)
  );
  for (const k of keys.slice(0, keys.length - 200)) delete staticData.sessions[k];
}

return [
  {
    json: {
      ok: true,
      sessionId: ctx.sessionId,
      action,
      target,
      openLink: intent.openLink === true,
      openExternal: intent.openExternal === true,
      url: intent.url ? String(intent.url) : "",
      reply,
      spoken: reply,
      extractedFields: intent.extractedFields || {},
      fillMode: intent.fillMode ?? null,
      endSession: intent.endSession === true,
      heardAs: intent.heardAs ? String(intent.heardAs) : "",
      remember: intent.remember || {},
      via,
      payload: {
        openLink: intent.openLink === true,
        openExternal: intent.openExternal === true,
        url: intent.url || undefined,
        click: true,
        fields: intent.extractedFields || undefined,
        heardAs: intent.heardAs || undefined,
        remember: intent.remember || undefined,
      },
    },
  },
];
